1	package meter
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“按实际发生时刻归入 UTC 自然月、同一时刻的不同表示不改变事件身份”
10	// 提供时区维度的回归保障：业务账户提交的事件时间可以携带任意正负偏移，
11	// 服务既不能按时间字面上的本地年月归账，也不能按上报时刻归账。
12	var (
13		zonePlus8   = time.FixedZone("UTC+8", 8*60*60)
14		zonePlus530 = time.FixedZone("UTC+5:30", 5*60*60+30*60)
15		zoneMinus5  = time.FixedZone("UTC-5", -5*60*60)
16	)
17	
18	// TestTimezoneOffsetAttributionAndBilling 覆盖题述完整正常使用链路：
19	// 账户自 2026-02-01 起使用同一套餐（月费 1000 分、含 10 单位、超额 100 分/单位、
20	// 税率 10%），两条事件都在实际发生后的 3 月补报；
21	// 本地钟面在 3 月的 +08:00 事件实际发生于 2 月，本地钟面在 2 月的 -05:00 事件
22	// 实际发生于 3 月。归期在上报返回值、各月累计用量与后续账单中必须一致。
23	func TestTimezoneOffsetAttributionAndBilling(t *testing.T) {
24		// 上报时刻为 3 月：归账只取决于事件实际发生时刻，与上报时刻无关。
25		s, clk := newTestService(utc(2026, 3, 15, 12, 0))
26		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
27		mustAccount(t, s, "a")
28		if err := s.Subscribe("a", "p", utc(2026, 2, 1, 0, 0)); err != nil {
29			t.Fatalf("subscribe: %v", err)
30		}
31	
32		// 本地钟面 2026-03-01 00:30（UTC+08:00）= 2026-02-28 16:30 UTC → 2 月，12 单位。
33		eventFeb := Event{
34			AccountID: "a", EventID: "evt-plus8-march-wall",
35			At:       time.Date(2026, time.March, 1, 0, 30, 0, 0, zonePlus8),
36			Quantity: 12,
37		}
38		// 本地钟面 2026-02-28 20:30（UTC-05:00）= 2026-03-01 01:30 UTC → 3 月，8 单位。
39		eventMar := Event{
40			AccountID: "a", EventID: "evt-minus5-february-wall",
41			At:       time.Date(2026, time.February, 28, 20, 30, 0, 0, zoneMinus5),
42			Quantity: 8,
43		}
44	
45		// 锁定测试前提：提交时间的本地年月与应归账期恰好相反，
46		// 任何按本地年月或上报时刻归账的实现都会在此暴露。
47		if eventFeb.At.Month() != time.March || eventMar.At.Month() != time.February {
48			t.Fatalf("submitted wall months = %s and %s, want March and February",
49				eventFeb.At.Month(), eventMar.At.Month())
50		}
51		if !eventFeb.At.UTC().Equal(utc(2026, 2, 28, 16, 30)) {
52			t.Fatalf("plus8 event instant = %v, want 2026-02-28 16:30 UTC", eventFeb.At.UTC())
53		}
54		if !eventMar.At.UTC().Equal(utc(2026, 3, 1, 1, 30)) {
55			t.Fatalf("minus5 event instant = %v, want 2026-03-01 01:30 UTC", eventMar.At.UTC())
56		}
57	
58		rFeb, err := s.RecordEvent(eventFeb)
59		if err != nil || !rFeb.Accepted || rFeb.Period != feb(2026) {
60			t.Fatalf("plus8 event result: %+v %v", rFeb, err)
61		}
62		rMar, err := s.RecordEvent(eventMar)
63		if err != nil || !rMar.Accepted || rMar.Period != mar(2026) {
64			t.Fatalf("minus5 event result: %+v %v", rMar, err)
65		}
66	
67		// 2 月只累计 12，3 月只累计 8；MonthlyUsage 与 Status 口径一致，且无其他月份。
68		if u, err := s.MonthlyUsage("a", feb(2026)); err != nil || u.Total != 12 {
69			t.Fatalf("feb usage = %+v %v, want 12", u, err)
70		}
71		if u, err := s.MonthlyUsage("a", mar(2026)); err != nil || u.Total != 8 {
72			t.Fatalf("mar usage = %+v %v, want 8", u, err)
73		}
74		st, err := s.Status("a")
75		if err != nil {
76			t.Fatal(err)
77		}
78		if len(st.MonthlyUsage) != 2 ||
79			st.MonthlyUsage[0] != (Usage{Period: feb(2026), Total: 12}) ||
80			st.MonthlyUsage[1] != (Usage{Period: mar(2026), Total: 8}) {
81			t.Fatalf("status monthly usage = %+v, want [feb 12, mar 8]", st.MonthlyUsage)
82		}
83	
84		wantTerms := PlanTerms{PlanID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000}
85	
86		// 2 月账期结束后出账：超额 2 单位，超额费 200 分，
87		// 税 (1000+200)*10% = 120 分，应付 1320 分，沿用完整月费、额度与税额规则。
88		febBill, err := s.CreateBill("a", feb(2026))
89		if err != nil {
90			t.Fatalf("create feb bill: %v", err)
91		}
92		wantFebBill := Bill{
93			AccountID: "a", Period: feb(2026), Terms: wantTerms,
94			TotalUsage: 12, IncludedUnits: 10, OverageUnits: 2,
95			MonthlyFee: 1000, OverageFee: 200, Tax: 120, TotalDue: 1320,
96			Paid: 0, Balance: 1320, Settled: false,
97			DueAt: utc(2026, 3, 8, 0, 0),
98		}
99		if febBill != wantFebBill {
100			t.Fatalf("feb bill = %+v, want %+v", febBill, wantFebBill)
101		}
102	
103		// 已出账后，换时区表示的同一事件重报仍成功（此处 2 月账单已过付款截止日，
104		// 账户处于欠费停用，重报同样不受影响）：返回原账期、不再累计。
105		if r, err := s.RecordEvent(Event{
106			AccountID: "a", EventID: eventFeb.EventID,
107			At: eventFeb.At.UTC(), Quantity: 12,
108		}); err != nil || r.Accepted || r.Period != feb(2026) {
109			t.Fatalf("utc replay after billed: %+v %v", r, err)
110		}
111		// 新事件标识即使发生在该已出账月份（本地 02-15 10:00 +08 == 02-15 02:00Z）也拒绝。
112		if _, err := s.RecordEvent(Event{
113			AccountID: "a", EventID: "new-feb-event",
114			At:       time.Date(2026, time.February, 15, 10, 0, 0, 0, zonePlus8),
115			Quantity: 1,
116		}); !errors.Is(err, ErrMonthBilled) {
117			t.Fatalf("new event in billed february = %v, want ErrMonthBilled", err)
118		}
119		if got, _ := s.GetBill("a", feb(2026)); got != febBill {
120			t.Fatalf("feb bill changed after replay/reject: %+v", got)
121		}
122		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 12 {
123			t.Fatalf("feb usage changed after billing: %d", u.Total)
124		}
125	
126		// 进入 4 月后为 3 月出账：8 单位未超 10 单位额度，无超额，
127		// 税 1000*10% = 100 分，应付 1100 分。
128		clk.t = utc(2026, 4, 1, 0, 0)
129		marBill, err := s.CreateBill("a", mar(2026))
130		if err != nil {
131			t.Fatalf("create mar bill: %v", err)
132		}
133		wantMarBill := Bill{
134			AccountID: "a", Period: mar(2026), Terms: wantTerms,
135			TotalUsage: 8, IncludedUnits: 10, OverageUnits: 0,
136			MonthlyFee: 1000, OverageFee: 0, Tax: 100, TotalDue: 1100,
137			Paid: 0, Balance: 1100, Settled: false,
138			DueAt: utc(2026, 4, 8, 0, 0),
139		}
140		if marBill != wantMarBill {
141			t.Fatalf("mar bill = %+v, want %+v", marBill, wantMarBill)
142		}
143		// 已出账后换 +08:00 表示重报 3 月事件（03-01 09:30 +08 == 01:30Z）：返回原账期。
144		if r, err := s.RecordEvent(Event{
145			AccountID: "a", EventID: eventMar.EventID,
146			At:       time.Date(2026, time.March, 1, 9, 30, 0, 0, zonePlus8),
147			Quantity: 8,
148		}); err != nil || r.Accepted || r.Period != mar(2026) {
149			t.Fatalf("mar replay after billed: %+v %v", r, err)
150		}
151		// 3 月新标识事件同样拒绝（本地 03-10 12:00 -05 == 03-10 17:00Z）。
152		if _, err := s.RecordEvent(Event{
153			AccountID: "a", EventID: "new-mar-event",
154			At:       time.Date(2026, time.March, 10, 12, 0, 0, 0, zoneMinus5),
155			Quantity: 1,
156		}); !errors.Is(err, ErrMonthBilled) {
157			t.Fatalf("new event in billed march = %v, want ErrMonthBilled", err)
158		}
159		if got, _ := s.GetBill("a", mar(2026)); got != marBill {
160			t.Fatalf("mar bill changed after replay/reject: %+v", got)
161		}
162	
163		// 最终：归期在上报返回值、各月累计与账单中始终一致，金额与用量固定。
164		st, err = s.Status("a")
165		if err != nil {
166			t.Fatal(err)
167		}
168		if len(st.MonthlyUsage) != 2 ||
169			st.MonthlyUsage[0] != (Usage{Period: feb(2026), Total: 12}) ||
170			st.MonthlyUsage[1] != (Usage{Period: mar(2026), Total: 8}) {
171			t.Fatalf("final monthly usage = %+v", st.MonthlyUsage)
172		}
173		if len(st.Bills) != 2 ||
174			st.Bills[0] != (BillSummary{Period: feb(2026), TotalDue: 1320, Paid: 0, Balance: 1320, Settled: false, DueAt: utc(2026, 3, 8, 0, 0)}) ||
175			st.Bills[1] != (BillSummary{Period: mar(2026), TotalDue: 1100, Paid: 0, Balance: 1100, Settled: false, DueAt: utc(2026, 4, 8, 0, 0)}) {
176			t.Fatalf("final bill summaries = %+v", st.Bills)
177		}
178	}
179	
180	// TestEventInstantIdentityAcrossTimezoneRepresentations 锁定事件身份规则：
181	// 同一实际时刻的任意时区表示（含非整点偏移）都是同一事件；保留本地钟面但换时区、
182	// 实际时刻改变时，同一事件标识必须冲突，且冲突不改变用量。
183	func TestEventInstantIdentityAcrossTimezoneRepresentations(t *testing.T) {
184		s, _ := newTestService(utc(2026, 3, 15, 12, 0))
185		mustPlan(t, s, Plan{ID: "p", TaxRateBasisPoints: 0})
186		mustAccount(t, s, "a")
187		if err := s.Subscribe("a", "p", utc(2026, 2, 1, 0, 0)); err != nil {
188			t.Fatal(err)
189		}
190	
191		// 原始表示：本地 03-01 00:30 +08，实际时刻 02-28 16:30Z，归入 2 月。
192		orig := Event{
193			AccountID: "a", EventID: "evt",
194			At:       time.Date(2026, time.March, 1, 0, 30, 0, 0, zonePlus8),
195			Quantity: 12,
196		}
197		r, err := s.RecordEvent(orig)
198		if err != nil || !r.Accepted || r.Period != feb(2026) {
199			t.Fatalf("original event: %+v %v", r, err)
200		}
201	
202		// 同一实际时刻的 -05:00 表示（本地 02-28 11:30）：重报成功，不再次累计。
203		sameMinus5 := Event{
204			AccountID: "a", EventID: "evt",
205			At:       time.Date(2026, time.February, 28, 11, 30, 0, 0, zoneMinus5),
206			Quantity: 12,
207		}
208		if !sameMinus5.At.Equal(orig.At) {
209			t.Fatal("test setup: minus5 representation is not the same instant")
210		}
211		if r, err := s.RecordEvent(sameMinus5); err != nil || r.Accepted || r.Period != feb(2026) {
212			t.Fatalf("minus5 same-instant replay: %+v %v", r, err)
213		}
214		// 非整点偏移 +05:30（本地 02-28 22:00）与纯 UTC 表示同样是同一事件。
215		samePlus530 := Event{
216			AccountID: "a", EventID: "evt",
217			At:       time.Date(2026, time.February, 28, 22, 0, 0, 0, zonePlus530),
218			Quantity: 12,
219		}
220		if !samePlus530.At.Equal(orig.At) {
221			t.Fatal("test setup: plus5:30 representation is not the same instant")
222		}
223		if r, err := s.RecordEvent(samePlus530); err != nil || r.Accepted || r.Period != feb(2026) {
224			t.Fatalf("plus5:30 same-instant replay: %+v %v", r, err)
225		}
226		if r, err := s.RecordEvent(Event{
227			AccountID: "a", EventID: "evt",
228			At: orig.At.UTC(), Quantity: 12,
229		}); err != nil || r.Accepted || r.Period != feb(2026) {
230			t.Fatalf("utc same-instant replay: %+v %v", r, err)
231		}
232	
233		// 保留本地钟面 03-01 00:30，但换用 -05:00：实际时刻变为 03-01 05:30Z（已是 3 月）。
234		shifted := Event{
235			AccountID: "a", EventID: "evt",
236			At:       time.Date(2026, time.March, 1, 0, 30, 0, 0, zoneMinus5),
237			Quantity: 12,
238		}
239		if shifted.At.Equal(orig.At) {
240			t.Fatal("test setup: shifted representation is unexpectedly the same instant")
241		}
242		if _, err := s.RecordEvent(shifted); !errors.Is(err, ErrEventConflict) {
243			t.Fatalf("same wall clock, shifted instant = %v, want ErrEventConflict", err)
244		}
245		// 数量不变、时刻改变也是冲突；时刻相同、数量改变同样冲突。
246		if _, err := s.RecordEvent(Event{
247			AccountID: "a", EventID: "evt",
248			At: shifted.At, Quantity: 99,
249		}); !errors.Is(err, ErrEventConflict) {
250			t.Fatalf("shifted instant with other qty = %v, want ErrEventConflict", err)
251		}
252		if _, err := s.RecordEvent(Event{
253			AccountID: "a", EventID: "evt",
254			At: orig.At.UTC(), Quantity: 13,
255		}); !errors.Is(err, ErrEventConflict) {
256			t.Fatalf("same instant with changed qty = %v, want ErrEventConflict", err)
257		}
258	
259		// 冲突既不增加用量，也不改变归期：2 月仍只累计 12，3 月没有任何用量。
260		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 12 {
261			t.Fatalf("feb usage after conflicts = %d, want 12", u.Total)
262		}
263		if u, _ := s.MonthlyUsage("a", mar(2026)); u.Total != 0 {
264			t.Fatalf("mar usage after conflicts = %d, want 0", u.Total)
265		}
266	}
267	
268	// TestUTCMonthBoundaryNanosecondAcrossZones 锁定 UTC 月初边界的纳秒精度：
269	// 零点前一纳秒归前一期，恰在零点归新一期；即使两条事件在提交时区显示同一个
270	// 本地月份，也不能混到一起。事件身份同样精确到纳秒，不能按秒截断比较。
271	func TestUTCMonthBoundaryNanosecondAcrossZones(t *testing.T) {
272		s, _ := newTestService(utc(2026, 3, 2, 12, 0))
273		mustPlan(t, s, Plan{ID: "p", TaxRateBasisPoints: 0})
274		mustAccount(t, s, "a")
275		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
276			t.Fatal(err)
277		}
278	
279		// +08:00 一侧：两条事件的本地钟面都显示在 3 月 1 日，却分属 2 月与 3 月。
280		// 本地 03-01 07:59:59.999999999 +08 == 02-28 23:59:59.999999999 UTC（前一纳秒）。
281		beforePlus8 := time.Date(2026, time.March, 1, 7, 59, 59, 999999999, zonePlus8)
282		// 本地 03-01 08:00:00 +08 == 03-01 00:00:00 UTC（恰在零点）。
283		exactPlus8 := time.Date(2026, time.March, 1, 8, 0, 0, 0, zonePlus8)
284		wantBeforeFeb := time.Date(2026, time.February, 28, 23, 59, 59, 999999999, time.UTC)
285		wantExactMar := time.Date(2026, time.March, 1, 0, 0, 0, 0, time.UTC)
286		if !beforePlus8.UTC().Equal(wantBeforeFeb) {
287			t.Fatalf("before instant = %v, want %v", beforePlus8.UTC(), wantBeforeFeb)
288		}
289		if !exactPlus8.UTC().Equal(wantExactMar) {
290			t.Fatalf("exact instant = %v, want %v", exactPlus8.UTC(), wantExactMar)
291		}
292		if beforePlus8.Month() != time.March || exactPlus8.Month() != time.March {
293			t.Fatalf("plus8 wall months = %s, %s, want both March", beforePlus8.Month(), exactPlus8.Month())
294		}
295		// MonthOf 只认实际时刻：给同一时刻挂上任何时区表示，账期不变。
296		if MonthOf(beforePlus8) != feb(2026) || MonthOf(beforePlus8.In(zoneMinus5)) != feb(2026) {
297			t.Fatal("one nanosecond before March must stay in February")
298		}
299		if MonthOf(exactPlus8) != mar(2026) || MonthOf(exactPlus8.In(zoneMinus5)) != mar(2026) {
300			t.Fatal("exact zero must fall in March")
301		}
302	
303		rBefore, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-before", At: beforePlus8, Quantity: 5})
304		if err != nil || !rBefore.Accepted || rBefore.Period != feb(2026) {
305			t.Fatalf("one-ns-before event: %+v %v", rBefore, err)
306		}
307		rExact, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-exact", At: exactPlus8, Quantity: 7})
308		if err != nil || !rExact.Accepted || rExact.Period != mar(2026) {
309			t.Fatalf("exact-zero event: %+v %v", rExact, err)
310		}
311		// 同一 UTC 秒内带纳秒分量的事件（本地 03-01 07:59:59.500000001 +08
312		// == 02-28 23:59:59.500000001 UTC），用于锁定身份比较不截断纳秒。
313		midInstant := time.Date(2026, time.February, 28, 23, 59, 59, 500000001, time.UTC)
314		rMid, err := s.RecordEvent(Event{
315			AccountID: "a", EventID: "ns-mid",
316			At: time.Date(2026, time.March, 1, 7, 59, 59, 500000001, zonePlus8), Quantity: 2,
317		})
318		if err != nil || !rMid.Accepted || rMid.Period != feb(2026) {
319			t.Fatalf("sub-second event: %+v %v", rMid, err)
320		}
321	
322		// -05:00 一侧的 1/2 月边界：两条事件本地钟面都显示在 1 月 31 日，却分属 1 月与 2 月。
323		// 本地 01-31 18:59:59.999999999 -05 == 01-31 23:59:59.999999999 UTC（前一纳秒）。
324		beforeMinus5 := time.Date(2026, time.January, 31, 18, 59, 59, 999999999, zoneMinus5)
325		// 本地 01-31 19:00:00 -05 == 02-01 00:00:00 UTC（恰在零点）。
326		exactMinus5 := time.Date(2026, time.January, 31, 19, 0, 0, 0, zoneMinus5)
327		if beforeMinus5.Month() != time.January || exactMinus5.Month() != time.January {
328			t.Fatalf("minus5 wall months = %s, %s, want both January", beforeMinus5.Month(), exactMinus5.Month())
329		}
330		if MonthOf(beforeMinus5) != jan(2026) || MonthOf(exactMinus5) != feb(2026) {
331			t.Fatalf("minus5 boundary periods = %s, %s, want 2026-01, 2026-02",
332				MonthOf(beforeMinus5), MonthOf(exactMinus5))
333		}
334		if r, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-before-jan", At: beforeMinus5, Quantity: 3}); err != nil || !r.Accepted || r.Period != jan(2026) {
335			t.Fatalf("jan one-ns-before event: %+v %v", r, err)
336		}
337		if r, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-exact-jan", At: exactMinus5, Quantity: 4}); err != nil || !r.Accepted || r.Period != feb(2026) {
338			t.Fatalf("feb exact-zero event: %+v %v", r, err)
339		}
340	
341		// 用量按纳秒边界各归各期：1 月 3，2 月 5+2+4=11，3 月 7。
342		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 3 {
343			t.Fatalf("jan usage = %d, want 3", u.Total)
344		}
345		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 11 {
346			t.Fatalf("feb usage = %d, want 11", u.Total)
347		}
348		if u, _ := s.MonthlyUsage("a", mar(2026)); u.Total != 7 {
349			t.Fatalf("mar usage = %d, want 7", u.Total)
350		}
351	
352		// 前一纳秒事件换 UTC 表示重报：同一事件，返回原账期 2 月，不再累计。
353		if r, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-before", At: wantBeforeFeb, Quantity: 5}); err != nil || r.Accepted || r.Period != feb(2026) {
354			t.Fatalf("utc replay of one-ns-before: %+v %v", r, err)
355		}
356		// 同一 UTC 秒内仅相差 1 纳秒、实际时刻已变：同一标识必须冲突——
357		// 防止把时刻截断到秒再比较。
358		if _, err := s.RecordEvent(Event{
359			AccountID: "a", EventID: "ns-mid",
360			At:       midInstant.Add(time.Nanosecond),
361			Quantity: 2,
362		}); !errors.Is(err, ErrEventConflict) {
363			t.Fatalf("one-nanosecond shift within same second = %v, want ErrEventConflict", err)
364		}
365		// 仅相差 1 纳秒、实际时刻已变：同一标识必须冲突——防止把时刻截断到秒再比较。
366		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-before", At: exactPlus8, Quantity: 5}); !errors.Is(err, ErrEventConflict) {
367			t.Fatalf("one-nanosecond shift = %v, want ErrEventConflict", err)
368		}
369		// 零点事件换 -05:00 表示（本地 02-28 19:00）重报：仍是同一事件，账期 3 月。
370		if r, err := s.RecordEvent(Event{AccountID: "a", EventID: "ns-exact", At: exactPlus8.In(zoneMinus5), Quantity: 7}); err != nil || r.Accepted || r.Period != mar(2026) {
371			t.Fatalf("minus5 replay of exact-zero: %+v %v", r, err)
372		}
373		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 11 {
374			t.Fatalf("feb usage after boundary replays = %d, want 11", u.Total)
375		}
376		if u, _ := s.MonthlyUsage("a", mar(2026)); u.Total != 7 {
377			t.Fatalf("mar usage after boundary replays = %d, want 7", u.Total)
378		}
379	
380		// “晚于当前时刻”的判定同样基于实际时刻而非本地钟面：
381		// 本地 03-02 21:00 +08 == 13:00Z，晚于当前 12:00Z。
382		if _, err := s.RecordEvent(Event{
383			AccountID: "a", EventID: "zoned-future",
384			At:       time.Date(2026, time.March, 2, 21, 0, 0, 0, zonePlus8),
385			Quantity: 1,
386		}); !errors.Is(err, ErrEventInFuture) {
387			t.Fatalf("zoned future event = %v, want ErrEventInFuture", err)
388		}
389	}
